import{_ as e,o as a,c as o,a3 as r}from"./chunks/framework.D1iekJsc.js";const p=JSON.parse('{"title":"이미지 모델 배포","description":"PC에 A1111 또는 ComfyUI 배포, MiniTavern LAN 이미지 생성; 클라우드 이미지 API 없을 때 로컬 Stable Diffusion.","frontmatter":{"title":"이미지 모델 배포","description":"PC에 A1111 또는 ComfyUI 배포, MiniTavern LAN 이미지 생성; 클라우드 이미지 API 없을 때 로컬 Stable Diffusion.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"이미지 모델 배포 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"PC에 A1111 또는 ComfyUI 배포, MiniTavern LAN 이미지 생성; 클라우드 이미지 API 없을 때 로컬 Stable Diffusion."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/local/image-gen"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/local/image-gen"}]]},"headers":[],"relativePath":"ko/local/image-gen/index.md","filePath":"ko/local/image-gen/index.md","lastUpdated":1787224147000}'),i={name:"ko/local/image-gen/index.md"};function n(d,t,l,s,c,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="이미지-모델-배포" tabindex="-1">이미지 모델 배포 <a class="header-anchor" href="#이미지-모델-배포" aria-label="Permalink to &quot;이미지 모델 배포&quot;">​</a></h1><p>MiniTavern은 클라우드 이미지（OpenAI / Gemini / OpenRouter / Qwen）와 <strong>로컬</strong> Stable Diffusion 계열을 지원합니다:</p><table tabindex="0"><thead><tr><th>로컬 백엔드</th><th>App 플랫폼</th><th>기본 포트</th></tr></thead><tbody><tr><td><a href="./a1111">AUTOMATIC1111 / SD WebUI</a></td><td>A1111(SD WebUI)</td><td><code>7860</code></td></tr><tr><td><a href="./comfyui">ComfyUI</a></td><td>ComfyUI</td><td><code>8188</code>（Desktop 흔히 <code>8000</code>）</td></tr></tbody></table><p>폰 MiniTavern은 <strong>폰에서</strong> 확산 모델을 돌리지 않습니다. 이미지는 PC（또는 클라우드 GPU）에서 생성되고, App은 요청·결과 표시만 합니다.</p><h2 id="필요한-것" tabindex="-1">필요한 것 <a class="header-anchor" href="#필요한-것" aria-label="Permalink to &quot;필요한 것&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>권장</th></tr></thead><tbody><tr><td>PC</td><td>Windows가 가장 수월; macOS / Linux도 가능</td></tr><tr><td>GPU</td><td><strong>NVIDIA 6GB+</strong> 편안（SD 1.5）; SDXL / 큰 모델 <strong>8–12GB+</strong></td></tr><tr><td>외장 GPU 없음</td><td>CPU（매우 느림）또는 클라우드 GPU 대여（시간당, 무료 아님）</td></tr><tr><td>네트워크</td><td>폰·PC 같은 Wi‑Fi（게스트 격리 금지）</td></tr><tr><td>디스크</td><td>모델 파일 흔히 <strong>2–10GB+</strong>/개, 여유 공간</td></tr></tbody></table><p>GPU 없고 배포도 싫으면: <a href="/ultra_guides/ko/free-cloud/#무료-이미지-생성">무료 클라우드 · 이미지</a>의 클라우드 무료 이미지（있으면）, 또는 채팅만.</p><h2 id="경로-선택" tabindex="-1">경로 선택 <a class="header-anchor" href="#경로-선택" aria-label="Permalink to &quot;경로 선택&quot;">​</a></h2><table tabindex="0"><thead><tr><th>도구</th><th>적합한 사람</th><th>난이도</th></tr></thead><tbody><tr><td><a href="./a1111">A1111</a></td><td>전통 WebUI, 파라미터 직관, 타번 생태계 흔한 연동</td><td>중</td></tr><tr><td><a href="./comfyui">ComfyUI</a></td><td>워크플로 / 신모델 지원 빠름; App은 내장 기본 workflow</td><td>중</td></tr></tbody></table><p>둘 다 마지막: <a href="./connect-app">MiniTavern 이미지 연결</a>.</p><h2 id="권장-읽기-순서" tabindex="-1">권장 읽기 순서 <a class="header-anchor" href="#권장-읽기-순서" aria-label="Permalink to &quot;권장 읽기 순서&quot;">​</a></h2><ol><li>하드웨어에 맞게 <a href="./a1111">A1111</a> 또는 <a href="./comfyui">ComfyUI</a> 설치·모델 다운로드</li><li><strong>API + LAN 리슨</strong>（각 튜토리얼）</li><li><a href="./connect-app">MiniTavern 연결</a> · 테스트</li><li>채팅에서 <code>/imagine</code> 또는 첨부 → 이미지（<a href="/ultra_guides/ko/manual/model-link#이미지-생성연결--응답-이미지--키워드">모델 연결 · 이미지</a>）</li><li><a href="/ultra_guides/ko/local/">로컬 모델</a> 개요로 돌아가기</li></ol><h2 id="중요-안내" tabindex="-1">중요 안내 <a class="header-anchor" href="#중요-안내" aria-label="Permalink to &quot;중요 안내&quot;">​</a></h2><ul><li>폰 주소는 PC <strong>LAN IP</strong>（예 <code>192.168.1.8</code>）, <strong><code>localhost</code> / <code>127.0.0.1</code> 금지</strong>.</li><li>A1111은 <strong><code>--api</code></strong> 필수; Web UI만으로는 부족.</li><li>ComfyUI는 <strong><code>--listen</code></strong>（또는 Desktop Listen <code>0.0.0.0</code>）이어야 폰 접근.</li><li>방화벽 포트 개방; 미인증 이미지 API를 공용망에 노출하지 말 것.</li><li>현재 App Comfy 기본 워크플로는 <strong>참고 이미지를 소비하지 않음</strong>; 얼굴 고정은 A1111 또는 참고 지원 클라우드 우선.</li></ul>',14)])])}const g=e(i,[["render",n]]);export{p as __pageData,g as default};
